// ---------------------------------------------------------------------------
// One reveal grammar for the whole route: 16px of travel against the top of the
// viewport, once, never on anything already on screen at load.

function useReveal() {
  const ref = useRef(null)
  useEffect(() => {
    const nodes = ref.current?.querySelectorAll('[data-reveal]')
    if (!nodes?.length) return
    if (!('IntersectionObserver' in window)) {
      nodes.forEach((n) => n.classList.add('is-in'))
      return
    }
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            e.target.classList.add('is-in')
            io.unobserve(e.target)
          }
        })
      },
      { rootMargin: '0px 0px -12% 0px', threshold: 0.01 },
    )
    nodes.forEach((n) => {
      if (n.getBoundingClientRect().top < window.innerHeight * 0.9) n.classList.add('is-in')
      else io.observe(n)
    })
    return () => io.disconnect()
  }, [])
  return ref
}

