      </div>
    </section>
  )
}

// ---------------------------------------------------------------------------

function Reserve({ config, setConfig, name, setName, email, setEmail, reserved, chosen, onSubmit }) {
  return (
    <section className="band band-paper reserve" id="reserve" aria-labelledby="reserve-title">
      <div className="band-inner reserve-inner">
        <div className="reserve-say" data-reveal>
          <header className="section-head section-head-tight">
            <p className="kicker">
              <span className="kicker-rule" aria-hidden="true" />
              Reserve
            </p>
            <h2 id="reserve-title">Hold one of the 200.</h2>
          </header>
          <p className="reserve-note">
            Reservations are not binding and no payment is taken now. We will write once, with the
            timing record of the movement allocated to you.
          </p>
          <ul className="reserve-steps">
            <li><span>01</span> You choose a finish and leave a name.</li>
            <li><span>02</span> We allocate a movement number against it.</li>
            <li><span>03</span> We write once, when yours comes off the bench.</li>
          </ul>
        </div>

        <div className="reserve-panel" data-reveal>
          {reserved ? (
            <div className="docket" role="status">
              <p className="docket-stamp">
                <Check size={14} strokeWidth={2.4} aria-hidden="true" /> Reserved
              </p>
              <p className="docket-line">
                Reserved. {name}, we have held one {chosen.name} movement at CHF{' '}
                {chf(chosen.price)} and will write to {email}. {chosen.lead}.
              </p>
              <dl className="docket-rows">
                <div>
                  <dt>Finish</dt>
                  <dd>{chosen.name}</dd>
                </div>
                <div>
                  <dt>Price</dt>
                  <dd>CHF {chf(chosen.price)}</dd>
                </div>
                <div>
                  <dt>Delivery</dt>
                  <dd>{chosen.lead}</dd>
                </div>
              </dl>
              <p className="docket-foot">
                Not binding, and nothing has been charged. Change anything by replying to that
                letter, or write to{' '}
                <a href="mailto:atelier@aubryvent.ch">atelier@aubryvent.ch</a>.
              </p>
            </div>
          ) : (
            <form onSubmit={onSubmit} className="form">
              <div className="field">
                <label htmlFor="config">Which finish?</label>
                <div className="select-wrap">
                  <select
                    id="config"
                    name="config"
                    required
                    value={config}
                    onChange={(e) => setConfig(e.target.value)}
                  >
                    <option value="">Choose a finish</option>
                    {CONFIGURATIONS.map((c) => (
                      <option key={c.id} value={c.id}>
                        {c.name} — CHF {chf(c.price)}
                      </option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="field">
                <label htmlFor="name">Your name</label>
                <input
                  id="name"
                  name="name"
                  type="text"
                  required
                  autoComplete="name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                />
              </div>

              <div className="field">
                <label htmlFor="email">Email</label>
                <input
                  id="email"
                  name="email"
                  type="email"
                  required
                  autoComplete="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
              </div>

              <button type="submit" className="btn btn-block">
                Reserve a movement
              </button>
              <p className="form-foot">Not binding. No payment is taken.</p>
            </form>
          )}
        </div>
      </div>
    </section>
  )
}

// ---------------------------------------------------------------------------

function SiteFooter() {
  return (
    <footer className="site-footer">
      <div className="footer-top">
        <div className="footer-brand">
          <p className="footer-mark">Aubry &amp; Vent</p>
          <p className="footer-line">Caliber 08 · Vallée de Joux</p>
        </div>
        <a className="footer-mail" href="mailto:atelier@aubryvent.ch">
          <Mail size={15} strokeWidth={1.6} aria-hidden="true" />
          atelier@aubryvent.ch
          <ArrowUpRight size={14} strokeWidth={1.6} aria-hidden="true" />
        </a>
        <nav className="footer-nav" aria-label="More">
          <a href="#specification">Servicing</a>
          <a href="#workshop">Provenance</a>
          <a href="#reserve">Terms of reservation</a>
        </nav>
      </div>

      <div className="footer-bottom">
        <p className="credits">
          Photographs, in order: hand-wound calibre and balance cock,{' '}
          <a href="https://www.flickr.com/photos/76491533@N00/6095265888" rel="noreferrer nofollow">
            GuySie
          </a>{' '}
          (CC BY-SA 2.0); train wheels,{' '}
          <a href="https://www.flickr.com/photos/76491533@N00/7483551136" rel="noreferrer nofollow">
            GuySie
          </a>{' '}
          (CC BY-SA 2.0); uncoiled mainspring,{' '}
          <a href="https://commons.wikimedia.org/w/index.php?curid=6096793" rel="noreferrer nofollow">
            Hustvedt
          </a>{' '}
          (CC BY-SA 3.0); bench lathe,{' '}
          <a href="https://commons.wikimedia.org/w/index.php?curid=27664029" rel="noreferrer nofollow">
            Zephyris
          </a>{' '}
          (CC BY-SA 3.0). They show other movements and other benches, not Caliber 08.
        </p>
        <p className="copyright">Aubry &amp; Vent. Caliber 08. © 2026.</p>
      </div>
    </footer>
  )
}
