/* ==========================================================================
   Aubry & Vent — Caliber 08

   Two grounds, and the split means something: the movement lives in the dark
   under a caseback, so the sections about the mechanism are dark and lit like
   the macro photography they sit next to. The sections that are paperwork —
   specification, finishes, reservation — are on paper. Colour is sampled from
   the movement itself: steel, gilt brass, and the ruby of a jewel.
   ========================================================================== */

:root {
  /* Ground */
  --ink: #14161a;
  --ink-2: #1a1d22;
  --ink-3: #23272e;
  --paper: #f2eee5;
  --paper-2: #e9e3d6;
  --paper-3: #ded7c7;

  /* Sampled from the movement */
  --steel: #99a1a8;
  --brass: #b98b3e;
  --brass-lit: #d8a busy;
  --ruby: #8c2f3d;

  /* Type colours */
  --on-dark: #ece8df;
  --on-dark-2: #a7aeb5;
  --on-dark-3: #757c84;
  --on-paper: #191b1e;
  --on-paper-2: #55595f;
  --on-paper-3: #7d8188;

  --line-dark: rgba(236, 232, 223, 0.14);
  --line-dark-soft: rgba(236, 232, 223, 0.075);
  --line-paper: rgba(25, 27, 30, 0.16);
  --line-paper-soft: rgba(25, 27, 30, 0.08);

  --display: 'Instrument Serif', 'Iowan Old Style', Georgia, serif;
  --sans: 'IBM Plex Sans', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --mono: 'IBM Plex Mono', ui-monospace, 'SF Mono', Menlo, monospace;

  /* 1.25 scale off 16px */
  --t-xs: 0.8rem;
  --t-s: 0.9375rem;
  --t-m: 1.0625rem;
  --t-l: 1.25rem;
  --t-xl: 1.563rem;
  --t-2xl: 1.953rem;
  --t-3xl: 2.441rem;
  --t-4xl: 3.052rem;

  --gutter: clamp(1.25rem, 5vw, 4.5rem);
  --maxw: 1220px;

  --ease-out: cubic-bezier(0.2, 0.8, 0.3, 1);
  --ease-in-out: cubic-bezier(0.6, 0, 0.3, 1);
  --t-fast: 130ms;
  --t-base: 190ms;
  --t-slow: 340ms;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 5.5rem;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--on-paper);
  font-family: var(--sans);
  font-size: var(--t-m);
  line-height: 1.62;
  font-feature-settings: 'kern' 1;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

img {
  display: block;
  max-width: 100%;
}

h1,
h2,
h3 {
  font-family: var(--display);
  font-weight: 400;
  letter-spacing: -0.015em;
  line-height: 1.06;
  margin: 0;
}

p {
  margin: 0;
  text-wrap: pretty;
}

a {
  color: inherit;
}

/* --- The ambient layer. One grammar for the whole route: colour and border
   move fast, anything that lifts moves a little slower, and focus is always
   the same brass ring. ---------------------------------------------------- */

a,
button,
select,
input,
summary,
.finish,
.slab {
  transition:
    color var(--t-fast) var(--ease-out),
    background-color var(--t-fast) var(--ease-out),
    border-color var(--t-fast) var(--ease-out),
    opacity var(--t-fast) var(--ease-out),
    box-shadow var(--t-base) var(--ease-out),
    transform var(--t-base) var(--ease-out);
}

:where(a, button, select, input):focus-visible {
  outline: 2px solid var(--brass);
  outline-offset: 3px;
  border-radius: 1px;
}

[data-reveal] {
  opacity: 0;
  transform: translateY(14px);
  transition:
    opacity var(--t-slow) var(--ease-out),
    transform var(--t-slow) var(--ease-out);
}

[data-reveal].is-in {
  opacity: 1;
  transform: none;
}

/* ==========================================================================
   Shared section furniture
   ========================================================================== */

.band {
  padding: clamp(4.5rem, 9vw, 8.5rem) 0;
  position: relative;
}

.band-inner {
  width: min(var(--maxw), 100%);
  margin: 0 auto;
  padding: 0 var(--gutter);
}

.band-dark {
  background: var(--ink);
  color: var(--on-dark);
}

.band-paper {
  background: var(--paper);
  color: var(--on-paper);
}

.band-paper + .band-paper {
  padding-top: 0;
}

.kicker {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--on-paper-3);
  display: flex;
  align-items: center;
  gap: 0.85rem;
  margin-bottom: 1.4rem;
}

.band-dark .kicker {
  color: var(--on-dark-3);
}

.kicker-rule {
  width: 2.25rem;
  height: 1px;
  background: var(--brass);
  flex: none;
}

.section-head {
  max-width: 52rem;
  margin-bottom: clamp(2.75rem, 5vw, 4.5rem);
}

.section-head-tight {
  margin-bottom: 2rem;
}

.section-head h2 {
  font-size: clamp(2.1rem, 4.4vw, var(--t-4xl));
}

.section-lede {
  margin-top: 1.5rem;
  max-width: 40ch;
  font-size: var(--t-l);
  color: var(--on-paper-2);
  line-height: 1.5;
}

.band-dark .section-lede {
  color: var(--on-dark-2);
}

.section-note {
  margin-top: 1.6rem;
  max-width: 46ch;
  font-family: var(--mono);
  font-size: var(--t-xs);
  line-height: 1.75;
  color: var(--on-dark-3);
  border-left: 1px solid var(--line-dark);
  padding-left: 1.1rem;
}

/* Buttons ---------------------------------------------------------------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-family: var(--mono);
  font-size: var(--t-s);
  letter-spacing: 0.05em;
  padding: 0.95rem 1.6rem;
  background: var(--brass);
  color: #14161a;
  border: 1px solid var(--brass);
  border-radius: 2px;
  text-decoration: none;
  cursor: pointer;
  font-weight: 500;
}

.btn:hover {
  background: #cb9d4c;
  border-color: #cb9d4c;
  transform: translateY(-1px);
}

.btn:active {
  transform: translateY(0);
  background: #a87b32;
}

.btn-small {
  padding: 0.55rem 1.05rem;
  font-size: var(--t-xs);
}

.btn-block {
  width: 100%;
  padding: 1.05rem 1.6rem;
}

.link-arrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-family: var(--mono);
  font-size: var(--t-s);
  text-decoration: none;
  color: var(--on-dark-2);
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
}

.link-arrow:hover {
  color: var(--on-dark);
  border-bottom-color: var(--brass);
}

.link-arrow svg {
  transition: transform var(--t-base) var(--ease-out);
}

.link-arrow:hover svg {
  transform: translateY(2px);
}

/* ==========================================================================
   Header
   ========================================================================== */

.site-header {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 50;
  display: flex;
  align-items: center;
  gap: 2rem;
  padding: 0.9rem var(--gutter);
  color: var(--on-dark);
  background: transparent;
  border-bottom: 1px solid transparent;
  transition:
    background-color var(--t-base) var(--ease-out),
    border-color var(--t-base) var(--ease-out),
    color var(--t-base) var(--ease-out);
}

.site-header.is-stuck {
  background: rgba(20, 22, 26, 0.94);
  backdrop-filter: blur(10px);
  border-bottom-color: var(--line-dark);
}

.wordmark {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  text-decoration: none;
  margin-right: auto;
}

.wordmark-name {
  font-family: var(--display);
  font-size: 1.3rem;
  letter-spacing: 0.005em;
}

.wordmark-sep {
  width: 1px;
  height: 0.95rem;
  background: var(--line-dark);
}

.wordmark-cal {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--on-dark-2);
}

.site-nav {
  display: flex;
  gap: 1.75rem;
}

.site-nav a {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.06em;
  text-decoration: none;
  color: var(--on-dark-2);
  padding: 0.35rem 0;
  border-bottom: 1px solid transparent;
}

.site-nav a:hover {
  color: var(--on-dark);
  border-bottom-color: var(--brass);
}

/* ==========================================================================
   Hero — full-bleed macro of a real movement, type sitting in the dark half.
   ========================================================================== */

.hero {
  position: relative;
  min-height: min(100svh, 900px);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  background: var(--ink);
  color: var(--on-dark);
  padding: 9rem var(--gutter) 0;
  overflow: hidden;
}

.hero-media {
  position: absolute;
  inset: 0;
}

.hero-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 68% 40%;
  filter: saturate(0.86) contrast(1.06) brightness(0.92);
}

.hero-scrim {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(to top, var(--ink) 4%, rgba(20, 22, 26, 0.86) 34%, rgba(20, 22, 26, 0.2) 72%),
    linear-gradient(to right, rgba(20, 22, 26, 0.92) 0%, rgba(20, 22, 26, 0.35) 55%, transparent 85%);
}

.hero-body,
.hero-figures {
  position: relative;
  width: min(var(--maxw), 100%);
  margin-inline: auto;
}

.hero-body {
  max-width: 46rem;
  padding-bottom: clamp(2.5rem, 5vw, 4rem);
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--on-dark-2);
  margin-bottom: 1.6rem;
}

.tick {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--brass);
  flex: none;
  animation: beat 2.4s var(--ease-in-out) infinite;
}

@keyframes beat {
  0%,
  70%,
  100% {
    opacity: 0.35;
    transform: scale(0.82);
  }
  12% {
    opacity: 1;
    transform: scale(1);
  }
}

.hero h1 {
  font-size: clamp(3.6rem, 11vw, 8.5rem);
  line-height: 0.92;
  letter-spacing: -0.03em;
  margin-bottom: 1.6rem;
}

.hero-lede {
  font-family: var(--display);
  font-size: clamp(1.35rem, 2.6vw, 1.95rem);
  line-height: 1.32;
  max-width: 26ch;
  color: var(--on-dark);
}

.hero-claim {
  margin-top: 1.5rem;
  max-width: 46ch;
  color: var(--on-dark-2);
  font-size: var(--t-m);
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1.1rem 2rem;
  margin-top: 2.6rem;
}

.hero-figures {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-top: 1px solid var(--line-dark);
  margin-bottom: 0;
}

.hero-figures div {
  padding: 1.4rem 1.5rem 1.6rem 0;
  border-right: 1px solid var(--line-dark-soft);
}

.hero-figures div:last-child {
  border-right: 0;
}

.hero-figures dt {
  font-family: var(--mono);
  font-size: 0.7rem;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--on-dark-3);
  margin-bottom: 0.4rem;
}

.hero-figures dd {
  margin: 0;
  font-family: var(--mono);
  font-size: clamp(1.5rem, 3vw, 2.1rem);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
  color: var(--on-dark);
}

.hero-figures dd span {
  font-size: 0.5em;
  color: var(--brass);
  margin-left: 0.15em;
}

/* ==========================================================================
   The power path
   ========================================================================== */

.stages {
  list-style: none;
  margin: 0;
  padding: 0;
  position: relative;
}

.stage-rail {
  position: absolute;
  left: 1.4rem;
  top: 0.75rem;
  bottom: 3rem;
  width: 1px;
  background: var(--line-dark);
}

.stage-rail-fill {
  position: absolute;
  inset: 0 0 auto 0;
  height: var(--progress, 0%);
  background: linear-gradient(to bottom, var(--brass), rgba(185, 139, 62, 0.35));
  transition: height 620ms var(--ease-in-out);
}

.stage {
  border-top: 1px solid var(--line-dark-soft);
  padding: clamp(2rem, 3.4vw, 3rem) 0;
}

.stage:first-child {
  border-top: 0;
  padding-top: 0;
}

.stage-row {
  display: grid;
  grid-template-columns: 6.5rem minmax(0, 1fr) 15rem;
  gap: clamp(1.5rem, 3vw, 3rem);
  align-items: start;
}

.stage-index {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.1rem;
  position: relative;
  z-index: 1;
  width: 2.8rem;
}

.stage-num {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.08em;
  color: var(--on-dark-3);
  background: var(--ink);
  padding: 0.1rem 0;
  width: 100%;
  text-align: center;
  transition: color var(--t-base) var(--ease-out);
}

.stage.is-reached .stage-num {
  color: var(--brass);
}

.stage-mark {
  display: grid;
  place-items: center;
  width: 2.8rem;
  height: 2.8rem;
  border: 1px solid var(--line-dark);
  border-radius: 50%;
  background: var(--ink);
  color: var(--on-dark-3);
  transition:
    color var(--t-base) var(--ease-out),
    border-color var(--t-base) var(--ease-out);
}

.stage.is-reached .stage-mark {
  color: var(--steel);
  border-color: rgba(236, 232, 223, 0.26);
}

.stage.is-live .stage-mark {
  color: var(--brass);
  border-color: rgba(185, 139, 62, 0.55);
}

.mark {
  width: 26px;
  height: 26px;
  overflow: visible;
}

/* The one authored motion on this page: each mark runs at the rate its stage
   runs at, wherever that rate can honestly be drawn. It only runs while the
   stage is on screen. */
.stage.is-live .m-spin .mark,
.stage.is-live .m-unwind .mark {
  animation: spin var(--period) linear infinite;
}

.stage.is-live .m-swing .mark {
  animation: swing var(--period) var(--ease-in-out) infinite;
}

.stage.is-live .m-escape .mark {
  animation: escape var(--period) steps(2, jump-none) infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes swing {
  0%,
  100% {
    transform: rotate(-26deg);
  }
  50% {
    transform: rotate(26deg);
  }
}

@keyframes escape {
  0% {
    transform: rotate(-7deg);
  }
  100% {
    transform: rotate(7deg);
  }
}

.stage-text h3 {
  font-size: clamp(1.5rem, 2.6vw, var(--t-2xl));
  margin-bottom: 0.7rem;
}

.stage-text p {
  color: var(--on-dark-2);
  max-width: 54ch;
}

.stage-figure {
  border-left: 1px solid var(--line-dark);
  padding-left: 1.35rem;
  padding-top: 0.2rem;
}

.stage-figure strong {
  display: block;
  font-family: var(--mono);
  font-weight: 400;
  font-variant-numeric: tabular-nums;
  font-size: clamp(1.6rem, 2.6vw, 2rem);
  line-height: 1.1;
  letter-spacing: -0.02em;
  color: var(--on-dark);
}

.stage-figure span {
  display: block;
  margin-top: 0.5rem;
  font-family: var(--mono);
  font-size: var(--t-xs);
  line-height: 1.6;
  letter-spacing: 0.04em;
  color: var(--on-dark-3);
}

.stage-photo {
  margin: 2rem 0 0 6.5rem;
  max-width: 44rem;
}

.stage-photo img {
  width: 100%;
  height: clamp(200px, 30vw, 330px);
  object-fit: cover;
  border: 1px solid var(--line-dark);
}

.stage[data-stage='mainspring'] .stage-photo img {
  object-position: 50% 45%;
  filter: invert(1) hue-rotate(180deg) saturate(0.2) brightness(0.92) contrast(1.15);
}

.stage-photo figcaption {
  margin-top: 0.8rem;
  font-family: var(--mono);
  font-size: var(--t-xs);
  color: var(--on-dark-3);
  letter-spacing: 0.02em;
}

/* ==========================================================================
   The layer stack — drawn to scale, front to back
   ========================================================================== */

.layers {
  background: var(--paper);
}

.stack-wrap {
  display: grid;
  grid-template-columns: 3.5rem minmax(0, 1.15fr) minmax(0, 1fr);
  gap: clamp(1.5rem, 3vw, 3.5rem);
  align-items: start;
}

.stack-scale {
  position: relative;
  justify-self: end;
  text-align: right;
  padding-top: 0.35rem;
  height: 100%;
  min-height: 17rem;
  font-family: var(--mono);
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  color: var(--on-paper-3);
}

.stack-scale-rule {
  position: absolute;
  right: -0.9rem;
  top: 0.8rem;
  bottom: 0.8rem;
  width: 1px;
  background: var(--line-paper);
}

.stack-scale-rule::before,
.stack-scale-rule::after {
  content: '';
  position: absolute;
  right: 0;
  width: 7px;
  height: 1px;
  background: var(--line-paper);
}

.stack-scale-rule::before {
  top: 0;
}

.stack-scale-rule::after {
  bottom: 0;
}

.stack-scale-top {
  position: absolute;
  top: 0;
  right: 0;
}

.stack-scale-bot {
  position: absolute;
  bottom: 0;
  right: 0;
}

.stack {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.slab {
  position: relative;
  display: flex;
  align-items: center;
  gap: 1rem;
  width: 100%;
  /* height is the real thickness: 1mm = 44px */
  min-height: calc(var(--mm) * 44px);
  padding: 0.5rem 1.1rem;
  border: 1px solid var(--line-paper);
  border-left: 3px solid var(--paper-3);
  background: linear-gradient(
    100deg,
    var(--paper-2) 0%,
    #f4f0e8 26%,
    var(--paper-2) 46%,
    #efeadf 74%,
    var(--paper-3) 100%
  );
  color: var(--on-paper);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.slab-body {
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(
    92deg,
    rgba(25, 27, 30, 0.055) 0 1px,
    transparent 1px 4px
  );
  opacity: 0.9;
  pointer-events: none;
}

.slab-name {
  position: relative;
  font-size: var(--t-s);
  font-weight: 500;
}

.slab-mm {
  position: relative;
  margin-left: auto;
  font-family: var(--mono);
  font-size: var(--t-xs);
  font-variant-numeric: tabular-nums;
  color: var(--on-paper-3);
}

.slab:hover {
  border-left-color: var(--brass);
  transform: translateX(4px);
}

.slab.is-open {
  border-left-color: var(--brass);
  border-color: rgba(25, 27, 30, 0.3);
  transform: translateX(14px);
  box-shadow: -10px 6px 0 -6px rgba(25, 27, 30, 0.16);
}

.slab.is-open .slab-mm {
  color: var(--on-paper);
}

.stack-notes {
  padding-top: 0.4rem;
}

.stack-note {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.4rem 1rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--line-paper);
}

.stack-note-name {
  font-family: var(--display);
  font-size: var(--t-xl);
  line-height: 1.15;
}

.stack-note-mm {
  font-family: var(--mono);
  font-size: var(--t-s);
  font-variant-numeric: tabular-nums;
  color: var(--brass);
  align-self: end;
}

.stack-note-text {
  grid-column: 1 / -1;
  color: var(--on-paper-2);
  max-width: 42ch;
}

.stack-caption {
  margin-top: 1.5rem;
  font-family: var(--mono);
  font-size: var(--t-xs);
  line-height: 1.75;
  color: var(--on-paper-3);
  max-width: 40ch;
}

/* ==========================================================================
   Specification
   ========================================================================== */

.spec {
  padding-top: clamp(4rem, 7vw, 6.5rem);
}

.spec-inner {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1fr);
  gap: clamp(2.5rem, 6vw, 5.5rem);
  align-items: center;
}

.spec-drawing {
  position: relative;
}

.plan {
  width: 100%;
  height: auto;
  color: var(--on-paper);
  overflow: visible;
}

.plan-edge {
  fill: var(--paper-2);
  stroke: var(--on-paper);
  stroke-width: 1.25;
}

.plan-hair {
  fill: none;
  stroke: var(--line-paper);
  stroke-width: 1;
  stroke-dasharray: 2 5;
}

.plan-part circle,
.plan-part path {
  fill: none;
  stroke: var(--on-paper-2);
  stroke-width: 1;
}

.plan-bridge path {
  fill: var(--paper-3);
  stroke: var(--on-paper);
  stroke-width: 1.15;
}

.plan-jewel {
  fill: var(--ruby);
  stroke: rgba(25, 27, 30, 0.4);
  stroke-width: 0.8;
}

.plan-balance circle,
.plan-balance path {
  fill: none;
  stroke: var(--brass);
  stroke-width: 1.15;
}

.plan-cock path {
  fill: none;
  stroke: var(--on-paper);
  stroke-width: 1.6;
}

.plan-label {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.08em;
  fill: var(--on-paper-3);
}

.plan-dim path {
  stroke: var(--brass);
  stroke-width: 1;
}

.plan-dim text {
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.06em;
  fill: var(--brass);
}

.spec-drawing-caption {
  margin-top: 1.4rem;
  font-family: var(--mono);
  font-size: var(--t-xs);
  line-height: 1.7;
  color: var(--on-paper-3);
  max-width: 34ch;
}

.spec-list {
  margin: 0;
  border-top: 1px solid var(--line-paper);
}

.spec-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1.5rem;
  padding: 0.85rem 0;
  border-bottom: 1px solid var(--line-paper-soft);
}

.spec-row:nth-child(1),
.spec-row:nth-child(6),
.spec-row:nth-child(9) {
  border-bottom-color: var(--line-paper);
}

.spec-row dt {
  font-size: var(--t-s);
  color: var(--on-paper-2);
}

.spec-row dd {
  margin: 0;
  font-family: var(--mono);
  font-size: var(--t-s);
  font-variant-numeric: tabular-nums;
  text-align: right;
  letter-spacing: -0.005em;
}

/* ==========================================================================
   Finishes
   ========================================================================== */

.finishes {
  padding-top: clamp(4rem, 7vw, 7rem);
  background: linear-gradient(to bottom, var(--paper) 0%, var(--paper-2) 100%);
}

.finish-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: var(--line-paper);
  border: 1px solid var(--line-paper);
}

.finish {
  display: flex;
  flex-direction: column;
  gap: 1.4rem;
  padding: clamp(1.5rem, 2.4vw, 2.1rem);
  background: var(--paper);
}

.finish:hover {
  background: #f7f4ed;
}

.finish.is-selected {
  background: #fbf8f1;
  box-shadow: inset 0 3px 0 0 var(--brass);
}

.finish-head h3 {
  font-size: var(--t-xl);
  line-height: 1.14;
  min-height: 2.3em;
}

.finish-price {
  margin-top: 0.9rem;
  font-family: var(--mono);
  font-size: clamp(1.35rem, 2.2vw, 1.7rem);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}

.finish-price .cur {
  font-size: 0.62em;
  color: var(--on-paper-3);
  letter-spacing: 0.06em;
  margin-right: 0.25em;
}

.finish-desc {
  font-size: var(--t-s);
  color: var(--on-paper-2);
  line-height: 1.55;
  flex: 1;
}

.finish-meta {
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
  padding-top: 1.2rem;
  border-top: 1px solid var(--line-paper-soft);
}

.finish-lead {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.03em;
  color: var(--on-paper);
}

.alloc {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.alloc-bar {
  display: block;
  height: 5px;
  background: var(--paper-3);
  position: relative;
  overflow: hidden;
}

.alloc-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: var(--pct);
  background: repeating-linear-gradient(
    90deg,
    var(--ruby) 0 2px,
    rgba(140, 47, 61, 0.55) 2px 4px
  );
}

.alloc-text {
  font-family: var(--mono);
  font-size: var(--t-xs);
  color: var(--on-paper-3);
  letter-spacing: 0.02em;
}

.alloc-text strong {
  font-weight: 500;
  color: var(--on-paper);
}

.finish-choose {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  width: 100%;
  padding: 0.75rem 0.9rem;
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.05em;
  background: transparent;
  color: var(--on-paper);
  border: 1px solid var(--line-paper);
  border-radius: 2px;
  cursor: pointer;
}

.finish-choose:hover {
  border-color: var(--on-paper);
}

.finish-choose-box {
  display: grid;
  place-items: center;
  width: 17px;
  height: 17px;
  flex: none;
  border: 1px solid var(--line-paper);
  border-radius: 50%;
  color: transparent;
}

.finish.is-selected .finish-choose {
  background: var(--on-paper);
  border-color: var(--on-paper);
  color: var(--paper);
}

.finish.is-selected .finish-choose-box {
  background: var(--brass);
  border-color: var(--brass);
  color: #14161a;
}

/* ==========================================================================
   Workshop
   ========================================================================== */

.workshop {
  padding: 0;
}

.workshop-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
  align-items: stretch;
}

.workshop-media {
  margin: 0;
  position: relative;
  min-height: 100%;
}

.workshop-media img {
  width: 100%;
  height: 100%;
  min-height: 26rem;
  object-fit: cover;
  object-position: 42% 55%;
  filter: saturate(0.55) contrast(1.05) brightness(0.78);
}

.workshop-media figcaption {
  position: absolute;
  left: 0;
  bottom: 0;
  right: 0;
  padding: 2.5rem 1.5rem 1.1rem;
  font-family: var(--mono);
  font-size: 0.72rem;
  letter-spacing: 0.03em;
  color: var(--on-dark-2);
  background: linear-gradient(to top, rgba(20, 22, 26, 0.9), transparent);
}

.workshop-body {
  padding: clamp(3.5rem, 7vw, 7rem) var(--gutter) clamp(3.5rem, 7vw, 7rem)
    clamp(2rem, 5vw, 4.5rem);
  max-width: 46rem;
}

.workshop-body .section-head {
  margin-bottom: 2.5rem;
}

.facts {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--line-dark-soft);
}

.facts li {
  display: grid;
  grid-template-columns: 8.5rem minmax(0, 1fr);
  gap: 1.5rem;
  padding: 1.35rem 0;
  border-bottom: 1px solid var(--line-dark-soft);
}

.fact-label {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.08em;
  color: var(--brass);
  padding-top: 0.28rem;
}

.facts p {
  color: var(--on-dark-2);
  font-size: var(--t-s);
  line-height: 1.65;
}

.facts li:nth-child(3) .fact-label,
.facts li:nth-child(5) .fact-label {
  font-size: var(--t-l);
  letter-spacing: 0.01em;
  color: var(--on-dark);
  padding-top: 0;
}

/* ==========================================================================
   Reserve
   ========================================================================== */

.reserve {
  background: var(--paper-2);
  padding-top: clamp(4.5rem, 9vw, 8rem);
}

.reserve-inner {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 25rem);
  gap: clamp(2.5rem, 6vw, 5rem);
  align-items: start;
}

.reserve-note {
  max-width: 40ch;
  color: var(--on-paper-2);
  font-size: var(--t-l);
  line-height: 1.5;
}

.reserve-steps {
  list-style: none;
  margin: 2.5rem 0 0;
  padding: 0;
  max-width: 34rem;
}

.reserve-steps li {
  display: flex;
  gap: 1.1rem;
  align-items: baseline;
  padding: 0.85rem 0;
  border-top: 1px solid var(--line-paper-soft);
  font-size: var(--t-s);
  color: var(--on-paper-2);
}

.reserve-steps span {
  font-family: var(--mono);
  font-size: var(--t-xs);
  color: var(--brass);
  flex: none;
}

.reserve-panel {
  background: var(--paper);
  border: 1px solid var(--line-paper);
  padding: clamp(1.5rem, 3vw, 2.1rem);
  position: sticky;
  top: 5.5rem;
}

.field {
  margin-bottom: 1.25rem;
}

.field label {
  display: block;
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--on-paper-3);
  margin-bottom: 0.5rem;
}

.field input,
.field select {
  width: 100%;
  font-family: var(--sans);
  font-size: var(--t-s);
  color: var(--on-paper);
  background: var(--paper-2);
  border: 1px solid var(--line-paper);
  border-radius: 2px;
  padding: 0.8rem 0.9rem;
}

.select-wrap {
  position: relative;
}

.select-wrap::after {
  content: '';
  position: absolute;
  right: 1rem;
  top: 50%;
  width: 7px;
  height: 7px;
  border-right: 1px solid var(--on-paper-2);
  border-bottom: 1px solid var(--on-paper-2);
  transform: translateY(-70%) rotate(45deg);
  pointer-events: none;
}

.field select {
  appearance: none;
  padding-right: 2.4rem;
  cursor: pointer;
}

.field input:hover,
.field select:hover {
  border-color: var(--on-paper-3);
}

.field input:focus,
.field select:focus {
  background: var(--paper);
  border-color: var(--brass);
}

.form-foot {
  margin-top: 1rem;
  font-family: var(--mono);
  font-size: var(--t-xs);
  color: var(--on-paper-3);
  text-align: center;
}

/* The confirmation, set like the docket that would travel with the movement. */

.docket-stamp {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ruby);
  border: 1px solid var(--ruby);
  border-radius: 2px;
  padding: 0.35rem 0.7rem;
  margin-bottom: 1.4rem;
}

.docket-line {
  font-family: var(--display);
  font-size: var(--t-xl);
  line-height: 1.28;
  margin-bottom: 1.5rem;
}

.docket-rows {
  margin: 0 0 1.4rem;
  border-top: 1px solid var(--line-paper);
}

.docket-rows div {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1rem;
  padding: 0.7rem 0;
  border-bottom: 1px solid var(--line-paper-soft);
}

.docket-rows dt {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--on-paper-3);
}

.docket-rows dd {
  margin: 0;
  font-family: var(--mono);
  font-size: var(--t-s);
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.docket-foot {
  font-size: var(--t-xs);
  line-height: 1.7;
  color: var(--on-paper-2);
}

.docket-foot a,
.footer-nav a,
.credits a {
  text-decoration: underline;
  text-underline-offset: 3px;
  text-decoration-color: var(--line-paper);
}

.docket-foot a:hover,
.credits a:hover {
  text-decoration-color: var(--brass);
}

/* ==========================================================================
   Footer
   ========================================================================== */

.site-footer {
  background: var(--ink);
  color: var(--on-dark);
  padding: clamp(3rem, 6vw, 5rem) var(--gutter) 2.5rem;
}

.footer-top,
.footer-bottom {
  width: min(var(--maxw), 100%);
  margin-inline: auto;
}

.footer-top {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 2rem 3rem;
  padding-bottom: 2.5rem;
  border-bottom: 1px solid var(--line-dark);
}

.footer-mark {
  font-family: var(--display);
  font-size: var(--t-2xl);
  line-height: 1.1;
}

.footer-line {
  margin-top: 0.4rem;
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.08em;
  color: var(--on-dark-3);
}

.footer-mail {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  margin-right: auto;
  font-family: var(--mono);
  font-size: var(--t-s);
  text-decoration: none;
  color: var(--on-dark);
  border-bottom: 1px solid var(--line-dark);
  padding-bottom: 0.35rem;
}

.footer-mail:hover {
  color: var(--brass);
  border-bottom-color: var(--brass);
}

.footer-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem;
}

.footer-nav a {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.05em;
  color: var(--on-dark-2);
  text-decoration-color: var(--line-dark);
}

.footer-nav a:hover {
  color: var(--on-dark);
  text-decoration-color: var(--brass);
}

.footer-bottom {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem 3rem;
  justify-content: space-between;
  padding-top: 1.75rem;
}

.credits {
  max-width: 64ch;
  font-size: 0.78rem;
  line-height: 1.7;
  color: var(--on-dark-3);
}

.credits a {
  color: var(--on-dark-2);
  text-decoration-color: var(--line-dark);
}

.copyright {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.06em;
  color: var(--on-dark-3);
  white-space: nowrap;
}

/* ==========================================================================
   Narrower screens
   ========================================================================== */

@media (max-width: 1080px) {
  .site-nav {
    display: none;
  }

  .spec-inner,
  .reserve-inner {
    grid-template-columns: minmax(0, 1fr);
  }

  .spec-drawing {
    max-width: 24rem;
  }

  .reserve-panel {
    position: static;
  }

  .workshop-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .workshop-media img {
    min-height: 20rem;
    max-height: 48vh;
  }

  .workshop-body {
    padding-inline: var(--gutter);
  }
}

@media (max-width: 900px) {
  .stack-wrap {
    grid-template-columns: 2.5rem minmax(0, 1fr);
  }

  .stack-notes {
    grid-column: 1 / -1;
    padding-top: 1.75rem;
  }

  .finish-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .finish-head h3 {
    min-height: 0;
  }
}

@media (max-width: 720px) {
  :root {
    --t-m: 1rem;
  }

  .hero {
    min-height: 100svh;
    padding-top: 7rem;
  }

  .hero-media img {
    object-position: 62% 42%;
  }

  .hero h1 {
    font-size: clamp(3rem, 17vw, 5rem);
  }

  .hero-lede {
    max-width: 20ch;
  }

  .hero-actions .btn {
    width: 100%;
  }

  .hero-figures {
    grid-template-columns: repeat(2, 1fr);
  }

  .hero-figures div {
    padding: 1rem 1rem 1.1rem 0;
    border-bottom: 1px solid var(--line-dark-soft);
  }

  .hero-figures div:nth-child(2n) {
    border-right: 0;
  }

  .hero-figures div:nth-last-child(-n + 2) {
    border-bottom: 0;
  }

  /* The stage rail keeps running down the left on mobile; the figure moves up
     under the name, where it is the first thing read after it. */
  .stage-row {
    grid-template-columns: 3.4rem minmax(0, 1fr);
    gap: 1rem;
    row-gap: 1.1rem;
  }

  .stage-index {
    width: 2.4rem;
  }

  .stage-mark {
    width: 2.4rem;
    height: 2.4rem;
  }

  .mark {
    width: 22px;
    height: 22px;
  }

  .stage-text h3 {
    font-size: 1.45rem;
  }

  .stage-figure {
    grid-column: 2;
    border-left: 0;
    border-top: 1px solid var(--line-dark);
    padding-left: 0;
    padding-top: 0.9rem;
  }

  .stage-figure strong {
    font-size: 1.5rem;
  }

  .stage-photo {
    margin-left: 0;
  }

  .stage-photo img {
    height: 200px;
  }

  .section-note {
    max-width: none;
  }

  .facts li {
    grid-template-columns: minmax(0, 1fr);
    gap: 0.45rem;
  }

  .docket-rows div {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.15rem;
  }

  .docket-rows dd {
    text-align: left;
  }

  .footer-bottom {
    flex-direction: column;
  }
}

@media (max-width: 380px) {
  .wordmark-sep,
  .wordmark-cal {
    display: none;
  }

  .slab-name {
    font-size: var(--t-xs);
  }
}

/* ==========================================================================
   Reduced motion — the still form. Nothing here is load-bearing: the marks
   keep their orientation, the rail keeps its fill, and the note in the power
   path still says what the rates are.
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  [data-reveal] {
    opacity: 1;
    transform: none;
  }

  .stage-rail-fill {
    transition: none;
  }
}

