import { chromium } from 'playwright'
const url = 'http://localhost:4173/'
const b = await chromium.launch()
const errs = []
async function shoot(w, h, tag) {
  const p = await b.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 })
  p.on('console', (m) => m.type() === 'error' && errs.push(tag + ': ' + m.text()))
  p.on('pageerror', (e) => errs.push(tag + ' pageerror: ' + e.message))
  p.on('requestfailed', (r) => errs.push(tag + ' reqfail: ' + r.url()))
  await p.goto(url, { waitUntil: 'networkidle' })
  await p.evaluate(async () => {
    await new Promise((r) => {
      let y = 0
      const step = () => {
        y += 700
        window.scrollTo(0, y)
        if (y < document.body.scrollHeight) setTimeout(step, 120)
        else setTimeout(() => { window.scrollTo(0, 0); setTimeout(r, 500) }, 500)
      }
      step()
    })
  })
  await p.waitForTimeout(700)
  await p.screenshot({ path: `.shots/${tag}-full.png`, fullPage: true })
  const ow = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth)
  console.log(tag, 'overflowX:', ow, 'height:', await p.evaluate(() => document.body.scrollHeight))
  return p
}
await shoot(1440, 900, 'desktop')
await shoot(390, 844, 'mobile')
console.log(errs.length ? errs.join('\n') : 'no console/network errors')
await b.close()
EOF
